{"edits":[{"path":"scripts/lib/paired-ablation.mjs","content":"import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

const DEFAULT_FIXTURE = new URL('../../shared/agent-dev/paired-ablation-fixture.json', import.meta.url);
const CONDITIONS = Object.freeze(['baseline', 'treatment']);

function assert(condition, message) {
  if (!condition) throw new Error(message);
}

function finite(value, name) {
  assert(typeof value === 'number' && Number.isFinite(value), `${name} must be a finite number`);
  return value;
}

function sha256(value) {
  return createHash('sha256').update(value).digest('hex');
}

function seededRandom(seed) {
  let state = Number.parseInt(sha256(String(seed)).slice(0, 13), 16) >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = state;
    value = Math.imul(value ^ (value >>> 15), value | 1);
    value ^= value + Math.imul(value ^ (value >>> 7), value | 61);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

function median(values) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
}

function percentile(values, p) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const index = (sorted.length - 1) * p;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  return lower === upper ? sorted[lower] : sorted[lower] + (sorted[upper] - sorted[lower]) * (index - lower);
}

function mean(values) {
  return values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
}

function standardDeviation(values) {
  if (values.length < 2) return 0;
  const average = mean(values);
  return Math.sqrt(values.reduce((sum, value) => sum + (value - average) ** 2, 0) / (values.length - 1));
}

function pairedEffect(differences) {
  const average = mean(differences);
  const standardError = standardDeviation(differences) / Math.sqrt(differences.length);
  return {
    estimate: average,
    ci95: [average - 1.96 * standardError, average + 1.96 * standardError],
    method: 'paired normal approximation',
    n: differences.length
  };
}

function bootstrapEffect(differences, seed, iterations = 10000) {
  if (!differences.length) return { estimate: null, ci95: [null, null], method: 'paired percentile bootstrap', n: 0 };
  const random = seededRandom(seed);
  const estimates = [];
  for (let iteration = 0; iteration < iterations; iteration += 1) {
    let sum = 0;
    for (let index = 0; index < differences.length; index += 1) {
      sum += differences[Math.floor(random() * differences.length)];
    }
    estimates.push(sum / differences.length);
  }
  estimates.sort((a, b) => a - b);
  return {
    estimate: mean(differences),
    ci95: [percentile(estimates, 0.025), percentile(estimates, 0.975)],
    method: 'paired percentile bootstrap',
    bootstrapIterations: iterations,
    n: differences.length
  };
}

function validateFixture(fixture) {
  assert(fixture && typeof fixture === 'object', 'fixture must be an object');
  assert(Array.isArray(fixture.cases) && fixture.cases.length >= 20, 'fixture must contain at least 20 cases');
  assert(Number.isInteger(fixture.repetitions) && fixture.repetitions >= 3, 'fixture repetitions must be an integer >= 3');
  assert(fixture.preregistration && typeof fixture.preregistration === 'object', 'fixture must contain preregistration');
  assert(fixture.preregistration.primaryMetric === 'passAt3', 'primary metric must be the preregistered passAt3');
  const ids = new Set();
  for (const testCase of fixture.cases) {
    assert(testCase && typeof testCase === 'object', 'each fixture case must be an object');
    assert(typeof testCase.id === 'string' && testCase.id.length > 0, 'each fixture case needs an id');
    assert(!ids.has(testCase.id), `duplicate fixture case id: ${testCase.id}`);
    ids.add(testCase.id);
    assert(Array.isArray(testCase.insertionOrder) && testCase.insertionOrder.length >= 2, `${testCase.id} needs at least two insertions`);
    assert(testCase.insertionOrder.every((id) => typeof id === 'string'), `${testCase.id} insertion ids must be strings`);
    assert(new Set(testCase.insertionOrder).size === testCase.insertionOrder.length, `${testCase.id} insertion order must be unique`);
    assert(typeof testCase.expectedSuccess === 'boolean', `${testCase.id} needs expectedSuccess`);
    assert(typeof testCase.falsePositiveExpected === 'boolean', `${testCase.id} needs falsePositiveExpected`);
    assert(typeof testCase.safetyCritical === 'boolean', `${testCase.id} needs safetyCritical`);
  }
  return fixture;
}

async function loadFixture(path = DEFAULT_FIXTURE) {
  const source = await readFile(path, 'utf8');
  const fixture = JSON.parse(source);
  validateFixture(fixture);
  return fixture;
}

function callFirst(target, methodNames, args = []) {
  for (const methodName of methodNames) {
    if (target && typeof target[methodName] === 'function') {
      return target[methodName](...args);
    }
  }
  return undefined;
}

async function resolveValue(value) {
  return value && typeof value.then === 'function' ? value : value;
}

function tokenProxy(text) {
  return Math.ceil(String(text).length / 4);
}

function retainedIds(store) {
  const value = callFirst(store, ['retainedIds', 'getRetainedIds', 'listRetainedIds', 'getEntries', 'entries', 'list']);
  if (Array.isArray(value)) return value.map((entry) => typeof entry === 'string' ? entry : entry?.id ?? entry?.key);
  if (value && typeof value === 'object') return Object.keys(value);
  return [];
}

async function snapshotStore(store) {
  const value = await resolveValue(callFirst(store, ['snapshot', 'inspect', 'debugSnapshot', 'getSnapshot']));
  if (!value) return { retainedIds: retainedIds(store), raw: undefined };
  const retained = Array.isArray(value.retainedIds)
    ? value.retainedIds
    : Array.isArray(value.entries)
      ? value.entries.map((entry) => entry?.id ?? entry?.key)
      : value;
  return {
    retainedIds: Array.isArray(retained) ? retained.map((entry) => typeof entry === 'string' ? entry : entry?.id ?? entry?.key) : [],
    raw: value
  };
}

async function insert(store, item) {
  const methods = ['insert', 'add', 'append', 'remember', 'put', 'write'];
  for (const method of methods) {
    if (typeof store?.[method] === 'function') {
      await resolveValue(store[method](item));
      return;
    }
  }
  throw new Error('RuntimeMemoryStore adapter exposes none of insert/add/append/remember/put/write');
}

async function evictToCapacity(store, capacity) {
  const methods = ['evictToCapacity', 'evict', 'trimToCapacity'];
  for (const method of methods) {
    if (typeof store?.[method] === 'function') {
      await resolveValue(store[method](capacity));
      return;
    }
  }
  throw new Error('RuntimeMemoryStore adapter exposes none of evictToCapacity/evict/trimToCapacity');
}

async function runCase({ store, testCase, condition, repetition, seed, observe }) {
  const started = performance.now();
  let success = false;
  let falsePositive = false;
  let safetyViolation = false;
  let output = '';
  let promptTokens = 0;
  let retainedBefore = [];
  let retainedAfter = [];
  try {
    for (const id of testCase.insertionOrder) {
      const message = testCase.messages.find((candidate) => candidate.id === id);
      assert(message, `${testCase.id} references unknown insertion ${id}`);
      const item = {
        id,
        text: message.text,
        type: message.type,
        tags: message.tags ?? [],
        metadata: message.metadata ?? {}
      };
      retainedBefore = (await snapshotStore(store)).retainedIds;
      await insert(store, item);
      promptTokens += tokenProxy(message.text);
      await evictToCapacity(store, testCase.capacity);
    }
    retainedAfter = (await snapshotStore(store)).retainedIds;
    const observation = await observe({ store, testCase, condition, repetition, seed, promptTokens });
    output = String(observation?.output ?? '');
    success = typeof observation?.success === 'boolean'
      ? observation.success
      : testCase.expectedSuccess && output.includes(testCase.expectedOutput);
    falsePositive = typeof observation?.falsePositive === 'boolean'
      ? observation.falsePositive
      : testCase.falsePositiveExpected && output.includes(testCase.falsePositiveMarker);
    safetyViolation = typeof observation?.safetyViolation === 'boolean'
      ? observation.safetyViolation
      : testCase.safetyCritical && output.includes(testCase.safetyViolationMarker);
  } catch (error) {
    success = false;
    safetyViolation = testCase.safetyCritical === true;
    output = error instanceof Error ? error.message : String(error);
  }
  const latencyMs = performance.now() - started;
  return {
    caseId: testCase.id,
    condition,
    repetition,
    seed,
    success,
    falsePositive,
    safetyViolation,
    latencyMs,
    promptTokens,
    output,
    retainedBefore,
    retainedAfter
  };
}

function summarize(rows) {
  const latencies = rows.map((row) => row.latencyMs);
  const successes = rows.filter((row) => row.success).length;
  const falsePositives = rows.filter((row) => row.falsePositive).length;
  const safetyViolations = rows.filter((row) => row.safetyViolation).length;
  return {
    n: rows.length,
    successRate: successes / rows.length,
    passAtK: rows.length ? successes / rows.length : null,
    passAt1: rows.length ? rows.filter((row) => row.repetition === 1 && row.success).length / new Set(rows.map((row) => row.caseId)).size : null,
    passAt3: rows.length ? successes / rows.length : null,
    latencyMs: { p50: median(latencies), p95: percentile(latencies, 0.95) },
    tokensProxy: { prompt: rows.reduce((sum, row) => sum + row.promptTokens, 0), meanPerCase: rows.length ? mean(rows.map((row) => row.promptTokens)) : null },
    falsePositives: { count: falsePositives, rate: falsePositives / rows.length },
    safetyViolations: { count: safetyViolations, rate: safetyViolations / rows.length }
  };
}

function pairRows(baseline, treatment) {
  const key = (row) => `${row.caseId}:${row.repetition}`;
  const treatmentByKey = new Map(treatment.map((row) => [key(row), row]));
  return baseline.map((row) => {
    const other = treatmentByKey.get(key(row));
    assert(other, `missing paired treatment row for ${key(row)}`);
    return { baseline: row, treatment: other };
  });
}

function effects(pairs, seed) {
  const success = pairs.map((pair) => Number(pair.treatment.success) - Number(pair.baseline.success));
  const falsePositive = pairs.map((pair) => Number(pair.treatment.falsePositive) - Number(pair.baseline.falsePositive));
  const safety = pairs.map((pair) => Number(pair.treatment.safetyViolation) - Number(pair.baseline.safetyViolation));
  const latency = pairs.map((pair) => pair.treatment.latencyMs - pair.baseline.latencyMs);
  const tokens = pairs.map((pair) => pair.treatment.promptTokens - pair.baseline.promptTokens);
  return {
    successRate: bootstrapEffect(success, `${seed}:success`),
    falsePositiveRate: bootstrapEffect(falsePositive, `${seed}:false-positive`),
    safetyViolationRate: bootstrapEffect(safety, `${seed}:safety`),
    latencyMs: pairedEffect(latency),
    tokensProxy: pairedEffect(tokens)
  };
}

function componentVerification(pairs) {
  const differences = pairs.filter((pair) => {
    const before = JSON.stringify(pair.baseline.retainedBefore) !== JSON.stringify(pair.treatment.retainedBefore);
    const after = JSON.stringify(pair.baseline.retainedAfter) !== JSON.stringify(pair.treatment.retainedAfter);
    return before || after;
  });
  return {
    componentObserved: differences.length > 0,
    differingPairs: differences.length,
    verified: differences.length > 0,
    note: differences.length === 0 ? 'No retained/evicted-set difference was observed; results are not evidence for the component.' : 'At least one paired retained/evicted set differs.'
  };
}

async function runPairedAblation(options) {
  assert(options && typeof options === 'object', 'options are required');
  const fixture = validateFixture(options.fixture ?? await loadFixture(options.fixturePath));
  assert(typeof options.createStore === 'function', 'createStore is required');
  assert(typeof options.observe === 'function', 'observe is required');
  assert(options.createStore.length >= 1, 'createStore must accept a condition so baseline/treatment use the same RuntimeMemoryStore implementation');
  const seed = options.seed ?? fixture.seed ?? 'paired-ablation-v1';
  const rows = { baseline: [], treatment: [] };
  for (const condition of CONDITIONS) {
    for (const testCase of fixture.cases) {
      for (let repetition = 1; repetition <= fixture.repetitions; repetition += 1) {
        const pairSeed = sha256(`${seed}:${condition}:${testCase.id}:${repetition}`);
        const store = await options.createStore({
          condition,
          case: testCase,
          repetition,
          seed: pairSeed,
          eviction: condition === 'treatment' ? 'type-aware' : 'fifo',
          ...(options.storeOptions ?? {})
        });
        assert(store, `createStore returned no store for ${condition}/${testCase.id}`);
        rows[condition].push(await runCase({
          store,
          testCase,
          condition,
          repetition,
          seed: pairSeed,
          observe: options.observe
        }));
      }
    }
  }
  const pairs = pairRows(rows.baseline, rows.treatment);
  return {
    schemaVersion: 1,
    fixtureId: fixture.id,
    fixtureSha256: sha256(JSON.stringify(fixture)),
    seed,
    design: {
      cases: fixture.cases.length,
      repetitions: fixture.repetitions,
      conditions: CONDITIONS,
      paired: true,
      isolatedStorePerRun: true,
      deterministicLocalFixture: true
    },
    preregistration: fixture.preregistration,
    componentVerification: componentVerification(pairs),
    conditions: {
      baseline: summarize(rows.baseline),
      treatment: summarize(rows.treatment)
    },
    effects: effects(pairs, seed),
    rows: [...rows.baseline, ...rows.treatment]
  };
}

async function loadRuntimeStoreFactory(modulePath) {
  assert(modulePath, 'runtime memory store module path is required');
  const module = await import(pathToFileURL(modulePath).href);
  const RuntimeMemoryStore = module.RuntimeMemoryStore ?? module.default?.RuntimeMemoryStore ?? module.default;
  assert(typeof RuntimeMemoryStore === 'function', 'runtime module must export RuntimeMemoryStore');
  return (options) => new RuntimeMemoryStore(options);
}

export {
  bootstrapEffect,
  componentVerification,
  conditions: CONDITIONS,
  effects,
  loadFixture,
  loadRuntimeStoreFactory,
  pairedEffect,
  percentile,
  runPairedAblation,
  summarize,
  tokenProxy,
  validateFixture
