  const fixture = validateFixture(options.fixture ?? await loadFixture(options.fixturePath));
  assert(typeof options.createStore === 'function', 'createStore is required');
  assert(typeof options.observe === 'function', 'observe is required');
  assert(options.createStore.length >= 1, 'createStore must accept a condition so baseline/treatment use the same RuntimeMemoryStore implementation');
  const seed = options.seed ?? fixture.seed ?? 'paired-ablation-v1';
  const rows = { baseline: [], treatment: [] };
  for (const condition of CONDITIONS) {
    for (const testCase of fixture.cases) {
      for (let repetition = 1; repetition <= fixture.repetitions; repetition += 1) {
        const pairSeed = sha256(`${seed}:${condition}:${testCase.id}:${repetition}`);
        const store = await options.createStore({
          condition,
          case: testCase,
          repetition,
          seed: pairSeed,
          eviction: condition === 'treatment' ? 'type-aware' : 'fifo',
          ...(options.storeOptions ?? {})
